#!/usr/bin/env python3
"""Generates data_quality_report.md and README_DATASET.md from measured outputs."""
import json, collections, csv
from pathlib import Path
OUT=Path("/mnt/user-data/outputs/data/rebuilt_v4")
CATS=["ipo_details","risk_factors","disclosures_and_definitions","legal_and_regulatory","promoters_and_management","company_information","financial_information","financial_statements","related_party_transactions","capital_structure","objects_of_issue","qualitative_factors","industry_information","business_operations","litigation","declarations","other"]
ST=json.load(open(OUT/"dataset_statistics.json")); SM=json.load(open(OUT/"split_manifest.json")); XS=json.load(open(OUT/"extraction_stats.json"))
OA=json.load(open(OUT/"old_data_audit.json")); OX=json.load(open(OUT/"old_data_audit_extra.json"))
M=[json.loads(l) for l in open(OUT/"master_sections.jsonl",encoding="utf-8")]
RQ=[json.loads(l) for l in open(OUT/"review_queue.jsonl",encoding="utf-8")]
man=[json.loads(l) for l in open(OUT/"model_ready_manifest.jsonl",encoding="utf-8")]
n=lambda p: sum(1 for _ in open(OUT/p,encoding="utf-8"))
fl=collections.Counter(f for r in M for f in r["quality_flags"])
rs=collections.Counter(r["review_status"] for r in M)
rsl={lv:collections.Counter(r["review_status"] for r in M if r["level"]==lv) for lv in (1,2)}
reasons=collections.Counter(x for q in RQ for x in q["reasons"])
cc=ST["category_counts_per_split"]
o=[]; w=o.append
w("# Data quality report — rebuilt_v4 (master + model-ready)\n")
w("Generated by `scripts/13_write_docs.py` from measured outputs. **All labels are provisional rule-derived labels; zero records are human-verified. No tokenizer check has been run. No model was trained.**\n")
w("## 1. Two different kinds of file\n")
w("| kind | file | records | what it is |\n|---|---|---:|---|")
w(f"| **MASTER** | `master_sections.jsonl` | {n('master_sections.jsonl')} | every extracted section (232 L1 chapters + 5,765 L2 sub-sections) with full raw+normalised text, page provenance, provisional label, review status and flags. The source of truth for everything derived. |")
w(f"| MASTER (support) | `extracted_sections.jsonl` | {n('extracted_sections.jsonl')} | same records before labeling (unlabeled extraction output) |")
w(f"| **MODEL-READY** | `train.jsonl` | {n('train.jsonl')} | derived instruction/input/output classification examples (4 documents) |")
w(f"| **MODEL-READY** | `validation.jsonl` | {n('validation.jsonl')} | derived examples (1 document: Century) |")
w(f"| **MODEL-READY** | `test.jsonl` | {n('test.jsonl')} | derived examples (1 document: Ideas) — frozen |")
w(f"| model-ready support | `model_ready_manifest.jsonl` | {n('model_ready_manifest.jsonl')} | provenance for every example (document, pages, source master ids, flags, truncation) — kept out of the prompt |")
w("| support | `split_manifest.json`, `dataset_statistics.json`, `review_queue.jsonl`, `label_audit_report.csv`, `duplicate_report.csv`, `model_ready_exclusions.csv`, `annotation_guidelines.md`, `extraction_report.md`, `extraction_issues.csv` | | reports and review material |")
w("\n## 2. Schemas\n")
w("**Model-ready example** (`train/validation/test.jsonl`, one JSON object per line):\n```json\n{\"example_id\": \"century-L2-006-066+1\", \"instruction\": \"Classify the following section ... Answer with the category name only.\", \"input\": \"Heading: <heading>\\n\\nText:\\n<section text, whitespace-collapsed, <= 2000 chars>\", \"output\": \"risk_factors\", \"label_status\": \"unverified_rule_label\"}\n```\n`output` is a separate field, so input truncation can never alter the target. The chat template is **not** applied; this is the plain instruction/input/output schema (I could not see your existing training pipeline, so compatibility is not confirmed). Drop `label_status` if your loader rejects extra keys, but keep the caveat.\n")
w("**Master record** (key fields): `example_id, document_id, source_filename, document_type, document_part, doc_date, company_name, level, parent_section_id, start_page, end_page, start_printed_page, end_printed_page, original_heading, normalized_heading, parent_heading, heading_path, heading_source, section_text_raw, section_text, n_chars, pages[], category, category_proposed[], label_basis, label_rule_id, label_confidence_tier (categorical, NOT a calibrated probability), label_status, review_status, quality_flags[], training_exclusion_reasons[], extraction_method, source_reference, tabular_line_ratio` (+ `toc`, `section_part`, `evidence` where applicable).\n")
w("## 3. Record counts\n")
w(f"Master: {len(M)} records. L1: {sum(rsl[1].values())} ({dict(rsl[1])}). L2: {sum(rsl[2].values())} ({dict(rsl[2])}).\n")
w("| split | documents | examples |\n|---|---|---:|")
for sp in ("train","validation","test"): w(f"| {sp} | {', '.join(SM['documents_by_split'][sp])} | {ST['examples_per_split'][sp]} |")
w(f"\nExamples per document: {ST['examples_per_document']}. {ST['n_master_L2_records_excluded_or_merged_away']} master L2 records are not a standalone example (excluded or merged); {ST['n_heading_only_records_merged']} heading-only records were merged forward into {ST['n_examples_with_merged_heading_only']} examples. Exclusion reasons (record counts): {ST['exclusion_reason_counts_master_L2_records']}.\n")
w("## 4. Category counts (model-ready examples, provisional labels)\n")
w("| category | train | validation | test | master L2 (all) |\n|---|---:|---:|---:|---:|")
for c in CATS: w(f"| {c} | {cc['train'].get(c,0)} | {cc['validation'].get(c,0)} | {cc['test'].get(c,0)} | {ST['master_category_counts_L2'].get(c,0)} |")
w(f"\nCategories absent from a split: {ST['categories_absent_per_split']} (`other` is never assigned automatically). Categories with <5 examples: {ST['categories_with_fewer_than_5_examples_per_split']}. **Per-category evaluation of `declarations` and `qualitative_factors` is not meaningful** on validation/test.\n")
w("## 5. Document-level split\n")
w("| document | type | split | examples |\n|---|---|---|---:|")
for d,v in SM["assignment"].items(): w(f"| {d} | {', '.join(v['document_type(s)'])} | **{v['split']}** | {v['examples']} |")
w(f"\n{SM['rationale']}\n\nLimitations:\n"+"\n".join(f"- {x}" for x in SM["limitations"])+"\n\n`split_manifest.json` also lists 6 leave-one-document-out folds.\n")
w("## 6. Leakage and duplicates\n")
d=ST["duplicates"]
w(f"Document-level separation verified (no document in two splits; AXIOM's abridged and RHP parts stay together). Near/exact duplicate pairs (5-word-shingle Jaccard ≥ 0.8): **{d['near_or_exact_pairs_jaccard_ge_0.8']}** total, {d['exact_text_pairs']} exact, {d['same_document_pairs']} within one document, **{d['cross_split_pairs']} across splits** (label conflicts among them: {d['cross_split_pairs_with_label_conflict']}). **{d['validation_examples_with_a_near_duplicate_in_train']} of {ST['examples_per_split']['validation']} validation examples and {d['test_examples_with_a_near_duplicate_in_train']} of {ST['examples_per_split']['test']} test examples have a near-duplicate in train** (shared boilerplate). They were reported, not removed; metrics on them are inflated. Details: `duplicate_report.csv`.\n")
w("## 7. Unresolved review flags\n")
w(f"- Master review_status: {dict(rs)} — **no record is `verified`**.\n- Review queue (`review_queue.jsonl`): {len(RQ)} records; reasons: {dict(reasons)}.")
w(f"- Flag counts across master: " + ", ".join(f"{k}={fl[k]}" for k in ["category_overlap_possible","heading_keyword_overrides_chapter_label","suspected_label_content_mismatch","fragment_heading_suspected","heading_is_paragraph_suspected","label_ambiguous_multi_topic_chapter","multi_topic_chapter_no_single_label","tiny_section","heading_only","very_long_section_not_split","table_heavy_check_structure","contains_scanned_page_with_embedded_ocr_layer","contains_image_only_page"]))
w("- Extraction issues carried over: see `extraction_report.md` (Quanto scanned financials excluded; risk-factor segmentation missing ~11% of numbered items; table structure unverified).")
w("- The `suspected_label_content_mismatch` heuristic fired on a small number of records; samples inspected looked like false alarms (e.g. a risk factor about negative cash flow). It is a weak second opinion, not a validation of the other labels.\n")
w("## 8. Truncation and tokenizer / target-preservation status\n")
t=ST["input_truncation"]
w(f"- Input text budget: **{ST['max_input_chars_setting']} characters** (heading budget {ST['max_heading_chars_setting']}); {t['examples_truncated']} examples ({round(100*t['share'],1)}%) are truncated; {ST['headings_truncated_in_prompt']} headings truncated. Median excerpt {t['excerpt_chars_median']} chars; median full section {t['full_chars_median']}, p95 {t['full_chars_p95']}, max {t['full_chars_max']:,}. Truncation is deterministic (cut at whitespace) and recorded per example in the manifest; full text stays in the master.")
w("- **Tokenizer / chat-template audit: NOT RUN.** No tokenizer was available and the target model is unknown. Token counts and sequence limits are therefore **unknown**; the character budget is a placeholder, not a token-derived limit.")
w("- What *was* verified without a tokenizer: the target is a separate `output` field (never part of truncated text); every output is a valid category; the excerpt equals / is an exact prefix of its source sections (4,425 full + 937 truncated checked).")
w("- To complete this check locally: `python scripts/14_audit_tokenizer.py --model <your model> --max-seq-len <N> --data-dir data/rebuilt_v4`. It checks prompt-prefix consistency, that target tokens decode to the category, and that right-truncation to N would not cut target tokens. I smoke-tested the script only with a toy character tokenizer; that says nothing about your tokenizer.\n")
w("## 9. Label-quality caveats you must know before training\n")
w(f"- Labels come from **chapter titles** (rule C01–C26, K, G, A rules), so a classifier can score well by learning headings. {round(100*ST['heading_equals_chapter_title_share'],1)}% of prompts have a heading equal to the chapter title. Report heading-ablated results if you want content-based claims.\n- Inherited labels mean many L2 sections in broad chapters (e.g. *Other Regulatory and Statutory Disclosures*, *Issue Procedure*) carry the chapter label whatever their content; `ipo_details` ({ST['master_category_counts_L2'].get('ipo_details')}) and `legal_and_regulatory` ({ST['master_category_counts_L2'].get('legal_and_regulatory')}) are large for that reason.\n- Evaluation against these labels measures agreement with the rules, not correctness.\n")
w("## 10. Comparison with the old dataset (measured only)\n")
nold=sum(r["old_section_count"] for r in OA["per_doc"].values()); mx=max(r["text_len_max"] for r in OA["per_doc"].values())
w(f"| check | old `sections.json` (6 docs) | rebuilt master |\n|---|---|---|\n| records | {nold} | {len(M)} ({sum(rsl[1].values())} L1 + {sum(rsl[2].values())} L2) |\n| largest section (chars) | {mx:,} | {max(r['n_chars'] for r in M):,} (flagged `very_long_section_not_split`) |\n| broken-word artifacts ('PRIV ATE', 'V ALID', …) | {sum(v['occurrences_in_old_sections_json'] for v in OX['artifact_strings'].values())} | 0 in PDF text layer (not re-extracted by OCR except flagged pages) |\n| `other`-labeled records | {OX['other_label']['n_other_in_6_docs']} ({round(100*OX['other_label']['n_other_in_6_docs']/OX['other_label']['n_sections_6_docs'])}%) | 0 (ambiguous items are flagged, not labeled) |\n| provenance | `heading, category, page_start, text` | document id, file, start/end page, printed page, raw+normalised text, rule id, flags |\n| text conservation | not testable | exact (independent non-whitespace char check, all docs) |\n| risk factors, Century | 1 record of 103,289 chars | split into individual numbered items (66 of ~73 isolated; see extraction report) |\n| label correctness | unknown | **also unknown** (rule-derived, unverified) |\n\nThe rebuild is demonstrably better on traceability, noise artifacts and segmentation granularity. It is **not** shown to be better on label correctness, because neither dataset has human-verified labels.\n")
w("## 11. Answers to the pre-training questions\n")
w(f"1. Sections per PDF: see `extraction_report.md` (L1/L2 per document).\n2. Master status: {dict(rs)}; verified = 0.\n3. Category counts: section 4.\n4. Flags: merged/truncated/corrupted/duplicated/mislabeled counts: flags in section 7; duplicates in section 6; confirmed mislabels: none *confirmed* (none verified) — suspected only.\n5. Thin categories: `qualitative_factors` (6 total), `declarations` (20 total; <5 in val/test), `related_party_transactions` (60), plus `other` (0).\n6. Test set document-disjoint: yes (verified), but it has {d['test_examples_with_a_near_duplicate_in_train']} examples with near-duplicates in train.\n7. Target preserved under the real tokenizer/chat template: **not checked** (see section 8).\n8. Unresolved: label verification, tokenizer audit, risk-factor segmentation gaps, table structure, Quanto scanned financials, fixed-price document type absent from eval.\n9. Strongest evidence of improvement: section 10 (traceability, artifacts, granularity).\n10. Fix before training: human review of at least the review queue and a sample of each category; run the tokenizer audit; decide on the `other` / `qualitative_factors` categories; consider heading-ablated evaluation. Safe to wait: table parsing, the 'ambiguous' General Information items beyond keyword rules.\n")
w("## 12. Generation order\n`01_extract_pages → 02_build_sections → 03_scan_inventory → 04_ocr_scanned → 06_extraction_report → 07_validate_extraction → 09_build_master → 11_build_model_ready → 12_validate_model_ready → 13_write_docs`. Run from `data/rebuilt_v4/`. `05*` audit the old files; `14_audit_tokenizer.py` is for local use.\n")
(OUT/"data_quality_report.md").write_text("\n".join(o),encoding="utf-8")
R=[]
R.append("# data/rebuilt_v4 — how to use\n")
R.append("**Provisional dataset.** Labels are rule-derived from chapter titles and unverified. Do not describe results as accuracy against human truth. No tokenizer audit has been run.\n")
R.append("## Master vs model-ready\n- **Master (source of truth):** `master_sections.jsonl` — all sections, full text, provenance, flags. Edit/review labels *here* (or in a copy), then regenerate derived files.\n- **Model-ready (derived):** `train.jsonl`, `validation.jsonl`, `test.jsonl` — instruction/input/output examples built from the master by `scripts/11_build_model_ready.py`. Provenance for each example is in `model_ready_manifest.jsonl` (join on `example_id`).\n")
R.append("## Load (Python)\n```python\nimport json\ndef load(p): return [json.loads(l) for l in open(p, encoding='utf-8')]\ntrain, val, test = (load(f'data/rebuilt_v4/{s}.jsonl') for s in ('train','validation','test'))\nmaster = load('data/rebuilt_v4/master_sections.jsonl')\n```\n")
R.append("## Before training\n1. Run `python scripts/14_audit_tokenizer.py --model <model> --max-seq-len <N> --data-dir data/rebuilt_v4` and read `tokenizer_audit_report.json`.\n2. Review `review_queue.jsonl` and spot-check labels using `annotation_guidelines.md`.\n3. Keep `test.jsonl` frozen (Ideas Electricals). See `split_manifest.json` for limits and leave-one-document-out folds.\n4. Read `data_quality_report.md` §4–§9.\n")
R.append("## Regenerate\nScripts in `scripts/` read the six source PDFs from the upload folder (paths are constants at the top of `01_extract_pages.py` and `03/04`); edit them for your machine. Nothing in this folder modifies your existing project files.\n")
(OUT/"README_DATASET.md").write_text("\n".join(R),encoding="utf-8")
print("written")
